// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.busimport com.roshan.persona.brain.intent.Intentimport com.roshan.persona.brain.trace.BrainTraceimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport kotlinx.coroutines.channels.BufferOverflowimport kotlinx.coroutines.flow.MutableSharedFlowimport kotlinx.coroutines.flow.SharedFlowimport kotlinx.coroutines.flow.asSharedFlowimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Brain bus. * * Pub-sub event bus for brain → features communication. Backed by Kotlin * [SharedFlow] with replay=0 (new subscribers don't see old events), * buffer capacity=64, drop-oldest overflow policy. * * Use cases: *   - Skill emits "user asked me to call mom" → Memory feature records it *   - Brain emits intent detected → Automation feature can trigger rules *   - Crash recovery emits session crashed → UI shows apology *   - Skill needs permission → UI shows permission prompt * * All events are in-memory only — never persisted to disk unless audit-flagged * (via [BrainEvent.shouldAudit] property). * * @see <a href="docs/spec/module2-spec-review.pdf">§3.4 BrainBus</a> */@Singletonclass BrainBus @Inject constructor() {    private val _events = MutableSharedFlow<BrainEvent>(        replay = 0,        extraBufferCapacity = DEFAULT_BUFFER_CAPACITY,        onBufferOverflow = BufferOverflow.DROP_OLDEST,    )    /** Public read-only flow. Subscribe via [events].collect { ... }. */    val events: SharedFlow<BrainEvent> = _events.asSharedFlow()    /** Emit an event. Suspends if buffer is full (rare due to DROP_OLDEST). */    suspend fun emit(event: BrainEvent) {        _events.emit(event)    }    /** Non-suspending emit. Returns false if dropped. */    fun tryEmit(event: BrainEvent): Boolean = _events.tryEmit(event)    companion object {        const val DEFAULT_BUFFER_CAPACITY = 64    }}/** * Events emitted through [BrainBus]. * * All events carry [correlationId] for tracing back to the originating request. */sealed interface BrainEvent {    /** Correlation ID of the originating request. */    val correlationId: CorrelationId    /** Whether this event should be audit-logged (persisted to Room). */    val shouldAudit: Boolean        get() = false    // ─── Layer 0 events ───────────────────────────────────────────────────    data class IntentClassified(        val intent: Intent,        val confidence: Float,        override val correlationId: CorrelationId,    ) : BrainEvent    // ─── Layer 1 events ───────────────────────────────────────────────────    data class RuleFired(        val ruleId: String,        val ruleTags: Set<String>,        override val correlationId: CorrelationId,    ) : BrainEvent {        override val shouldAudit = true    }    // ─── Layer 2 events ───────────────────────────────────────────────────    data class SkillInvoked(        val skillId: String,        val intentLabel: String,        override val correlationId: CorrelationId,    ) : BrainEvent {        override val shouldAudit = true    }    data class SkillNeedsPermission(        val skillId: String,        val permission: String,        override val correlationId: CorrelationId,    ) : BrainEvent    data class SkillNeedsInput(        val skillId: String,        val prompt: String,        override val correlationId: CorrelationId,    ) : BrainEvent    // ─── Layer 3 + 4 events ───────────────────────────────────────────────    data class LlmCallStarted(        val provider: String,  // "local" / "openai" / "anthropic" / "gemini"        val modelId: String,        override val correlationId: CorrelationId,    ) : BrainEvent {        override val shouldAudit = true    }    data class LlmCallCompleted(        val provider: String,        val modelId: String,        val tokensGenerated: Int,        val durationMs: Long,        val costUsd: Float,        override val correlationId: CorrelationId,    ) : BrainEvent {        override val shouldAudit = true    }    data class LlmCallFailed(        val provider: String,        val modelId: String,        val error: AppError,        override val correlationId: CorrelationId,    ) : BrainEvent    // ─── Brain orchestrator events ────────────────────────────────────────    data class BrainRequestCompleted(        val trace: BrainTrace,        override val correlationId: CorrelationId,    ) : BrainEvent {        override val shouldAudit = true    }    data class BrainRequestFailed(        val error: AppError,        val userMessage: String,        override val correlationId: CorrelationId,    ) : BrainEvent {        override val shouldAudit = true    }}